import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import crypto from 'node:crypto';
import { execFileSync } from 'node:child_process';

const work = process.argv[2];
if (!work || !fs.existsSync(work)) throw new Error('Payments/mobile patch: reconstructed work directory is required');

const b64 = '';
const archive = Buffer.from(b64, 'base64');
const expectedArchiveHash = 'cd1dcba1f36ccb6565f4bea72af63824192ac0647e4a84bf20f773006fb891de';
const actualArchiveHash = crypto.createHash('sha256').update(archive).digest('hex');
if (actualArchiveHash !== expectedArchiveHash) throw new Error(`Payments/mobile patch archive hash mismatch: ${actualArchiveHash}`);

const archivePath = path.join(os.tmpdir(), `transsalomao-payments-mobile-${process.pid}.tar.xz`);
fs.writeFileSync(archivePath, archive);
try {
  execFileSync('xz', ['-t', archivePath], { stdio: 'inherit' });
  execFileSync('tar', ['-xJf', archivePath, '-C', work], { stdio: 'inherit' });
} finally {
  fs.rmSync(archivePath, { force: true });
}

const checks = {
  'src/routes/dono/pagamentos.tsx': 'c73694987d43d9597df7095735c5e3e04cbeaeee24b8beba15876b41053359e9',
  'src/lib/driver-payments.ts': '032e598eaadf796c576f7464311313ae2cad1a7df7661c4d5f24f9773e68bae2',
};
for (const [rel, expected] of Object.entries(checks)) {
  const file = path.join(work, rel);
  if (!fs.existsSync(file)) throw new Error(`Payments/mobile patch missing file: ${rel}`);
  const actual = crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex');
  if (actual !== expected) throw new Error(`Payments/mobile patch file mismatch: ${rel}`);
}

console.log('[payments-acertos-mobile] Pagamentos + Acertos + Adiantamentos + saldo por motorista + mobile applied');
